// src/lib/plattform/ki/index.js
//
// Ablauf eines Assistenten-Aufrufs (nur serverseitig):
//   1. Anwendungsfall + Rolle prüfen, Rate-Limit je Konto und IP
//   2. Eingaben prüfen (Länge, Typ)
//   3. Kontext bauen – die Rechteprüfung passiert DABEI im Backend (fremdes Objekt → 403/404,
//      bevor irgendein Inhalt zusammengestellt ist)
//   4. Tages-Kontingent prüfen
//   5. KI-Modus (Claude API) – oder regelbasiert, wenn kein Schlüssel gesetzt ist bzw. der Dienst
//      ausfällt. Nie ein Fehler nur wegen fehlender KI.
//   6. Nutzung protokollieren (ohne Inhalte)
//
// Antwort (JSON): { ok, fall, modus: "ki"|"regel", ergebnis, quellen, hinweis, kontingent }
// Streaming (NDJSON, nur Textfälle im KI-Modus): {t:"start",…} {t:"text",text} … {t:"ende"} | {t:"ersetzen",…}

import { PlattformFehler } from "../fehler";
import { rateLimit } from "../server/rateLimit";
import { ANWENDUNGSFAELLE, kiAktiv, RATE_IP, RATE_KONTO, rateFaktor } from "./konfig";
import { erstellen, streamen, KiFehler } from "./client";
import * as P from "./prompts";
import { kontextExpose, kontextFlaeche, kontextFrage, kontextNachricht, kontextTriage } from "./kontext";
import { regelExpose, regelFlaeche, regelFrage, regelNachricht, regelTriage } from "./regeln";
import { kontingent, kontingentPruefen, protokollieren } from "./nutzung";
import { suchen, wissensBlock } from "./wissen";

export { kiAktiv } from "./konfig";
export { kontingent } from "./nutzung";

const HINWEIS_REGEL = "Regelbasierter Vorschlag – der KI-Assistent ist auf dieser Plattform nicht aktiviert.";
const HINWEIS_AUSFALL = "Der KI-Dienst ist gerade nicht erreichbar – hier ein regelbasierter Vorschlag.";

/** Darf dieser Nutzer den Anwendungsfall nutzen? (Admin darf alles) */
export function darfFall(fall, n) {
  const f = ANWENDUNGSFAELLE[fall];
  if (!f || !n) return false;
  const admin = n.rollen?.includes("admin");
  if (admin) return true;
  if (f.admin) return false;
  if (!f.rollen) return true;
  return f.rollen.some((r) => n.rollen?.includes(r));
}

export function erlaubteFaelle(n) {
  return Object.keys(ANWENDUNGSFAELLE).filter((f) => darfFall(f, n));
}

function text(wert, { min = 0, max, feld }) {
  if (wert === undefined || wert === null) wert = "";
  if (typeof wert !== "string") throw new PlattformFehler(422, `${feld}: ungültige Eingabe.`);
  const t = wert.replace(/\r/g, "").replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, "").trim();
  if (t.length < min) throw new PlattformFehler(422, min > 1 ? `${feld}: bitte mindestens ${min} Zeichen.` : `${feld} fehlt.`);
  if (t.length > max) throw new PlattformFehler(422, `${feld}: höchstens ${max} Zeichen.`);
  return t;
}

const liste = (x, max, laenge) => (Array.isArray(x) ? x : []).map((s) => String(s || "").trim()).filter(Boolean).slice(0, max).map((s) => (s.length > laenge ? `${s.slice(0, laenge - 1).trimEnd()}…` : s));

// ------------------------------------------------------------------ Anwendungsfälle

const FAELLE = {
  expose: {
    async kontext(b, n, body) {
      return kontextExpose(b, n, { projektId: body.projektId });
    },
    json: true,
    ki: (k) => ({ system: [P.BASIS, P.EXPOSE], nachricht: P.nachrichtExpose(k.daten), schema: P.EXPOSE_SCHEMA, effort: "medium", maxTokens: 6000 }),
    bereinigen: (j) => ({ beschreibung: String(j.beschreibung || "").trim().slice(0, 4000), highlights: liste(j.highlights, 6, 90), risiken: liste(j.risiken, 6, 300), fehlendeAngaben: liste(j.fehlendeAngaben, 12, 200) }),
    regel: (k) => regelExpose(k),
  },
  triage: {
    async kontext(b, n, body) {
      return kontextTriage(b, n, { vorgangId: body.vorgangId });
    },
    json: true,
    ki: (k) => ({ system: [P.BASIS, P.TRIAGE], nachricht: P.nachrichtTriage(k.daten), schema: P.TRIAGE_SCHEMA, effort: "low", maxTokens: 4000 }),
    bereinigen: (j, k) => ({
      zusammenfassung: String(j.zusammenfassung || "").slice(0, 1500),
      typVorschlag: j.typVorschlag || k.meta.vorgang.typ,
      prioritaet: ["hoch", "mittel", "niedrig"].includes(j.prioritaet) ? j.prioritaet : "mittel",
      begruendung: String(j.begruendung || "").slice(0, 500),
      fehlendeAngaben: liste(j.fehlendeAngaben, 10, 200),
      naechsterSchritt: String(j.naechsterSchritt || "").slice(0, 500),
      antwortEntwurf: String(j.antwortEntwurf || "").slice(0, 4000),
    }),
    regel: (k) => regelTriage(k),
  },
  frage: {
    eingaben: (body) => ({ frage: text(body.frage, { min: 3, max: 800, feld: "Frage" }) }),
    async kontext(b, n, body) {
      return kontextFrage(b, n, { projektId: body.projektId });
    },
    quellen: (k) => k.quellen.map((q) => ({ id: q.id, titel: q.titel, text: q.text.slice(0, 400) })),
    ki: (k, e) => ({ system: [P.BASIS, P.FRAGE], nachricht: P.nachrichtFrage({ projekttitel: k.daten.projekttitel, quellen: k.quellen, frage: e.frage }), effort: "medium", maxTokens: 4000 }),
    regel: (k, e) => {
      const r = regelFrage(k, e.frage);
      return { text: r.text };
    },
  },
  flaeche: {
    eingaben: (body) => ({ frage: text(body.frage, { max: 800, feld: "Frage" }) }),
    async kontext(b, n, body) {
      return kontextFlaeche(b, n, { flaecheId: body.flaecheId });
    },
    quellen: (k, e) => (e.frage ? suchen(e.frage, { anzahl: 3 }) : suchen(`${k.meta.flaeche.agri ? "agri-pv" : "pacht"} solarpark fläche`, { anzahl: 2 })).map((t) => ({ titel: t.titel, href: t.href })),
    ki: (k, e) => ({ system: [P.BASIS, P.FLAECHE, wissensBlock()], nachricht: P.nachrichtFlaeche(k.daten, e.frage), effort: "low", maxTokens: 3000 }),
    regel: (k, e) => ({ text: regelFlaeche(k, e.frage).text }),
  },
  nachricht: {
    eingaben: (body) => ({ stichpunkte: text(body.stichpunkte, { max: 1500, feld: "Stichpunkte" }) }),
    async kontext(b, n, body) {
      return kontextNachricht(b, n, { bezugArt: body.bezugArt, bezugId: body.bezugId });
    },
    ki: (k, e) => ({ system: [P.BASIS, P.NACHRICHT], nachricht: P.nachrichtEntwurf(k.daten, e.stichpunkte), effort: "low", maxTokens: 2000 }),
    regel: (k, e) => ({ text: regelNachricht(k, e.stichpunkte) }),
  },
};

function limitieren(n, ip) {
  const f = rateFaktor();
  rateLimit(`ki-konto:${n.id}`, Math.max(1, Math.round(RATE_KONTO[0] * f)), RATE_KONTO[1]);
  rateLimit(`ki-ip:${ip || "ohne-ip"}`, Math.max(1, Math.round(RATE_IP[0] * f)), RATE_IP[1]);
}

const zeile = (o) => `${JSON.stringify(o)}\n`;

/**
 * Führt einen Anwendungsfall aus. Liefert ein JSON-Objekt oder eine Streaming-Response.
 * `stream` (Body) = true wünscht Streaming; nur für Textfälle im KI-Modus.
 */
export async function ausfuehren({ fall, nutzer: n, body = {}, backend: b, ip = "" }) {
  const def = FAELLE[fall];
  if (!def) throw new PlattformFehler(404, "Unbekannter Anwendungsfall.");
  if (!darfFall(fall, n)) throw new PlattformFehler(403, "Dieser Assistent steht Ihrer Rolle nicht zur Verfügung.");
  limitieren(n, ip);
  const eingaben = def.eingaben ? def.eingaben(body) : {};

  // Rechteprüfung passiert hier – bei fremden Objekten wird ein 403/404 geworfen, bevor Kontext entsteht
  const k = await def.kontext(b, n, body);
  const kont = await kontingentPruefen(n);
  const quellen = def.quellen ? def.quellen(k, eingaben) : [];
  const basis = { ok: true, fall, quellen, kontingent: { limit: kont.limit, rest: Math.max(0, kont.rest - 1) } };
  const prot = { fall, objektArt: k.objektArt, objektId: k.objektId };

  const regelAntwort = async (hinweis, ergebnis = "ok") => {
    await protokollieren(n, { ...prot, modus: "regel", ergebnis });
    return { ...basis, modus: "regel", ergebnis: def.regel(k, eingaben), hinweis };
  };

  if (!kiAktiv()) return regelAntwort(HINWEIS_REGEL);

  const anfrage = def.ki(k, eingaben);

  // Strukturierte Fälle (Exposé, Triage): eine Anfrage, JSON-Schema
  if (def.json) {
    try {
      const r = await erstellen(anfrage);
      await protokollieren(n, { ...prot, modus: "ki", tokensEin: r.nutzung.ein, tokensAus: r.nutzung.aus });
      return { ...basis, modus: "ki", ergebnis: def.bereinigen(r.json, k), hinweis: "" };
    } catch (e) {
      if (!(e instanceof KiFehler)) throw e;
      return regelAntwort(e.art === "abgelehnt" ? "Der KI-Dienst hat diese Anfrage nicht bearbeitet – hier ein regelbasierter Vorschlag." : HINWEIS_AUSFALL, `ki-${e.art}`);
    }
  }

  // Textfälle: ohne Streaming-Wunsch eine normale Anfrage
  if (body.stream !== true) {
    try {
      const r = await erstellen(anfrage);
      await protokollieren(n, { ...prot, modus: "ki", tokensEin: r.nutzung.ein, tokensAus: r.nutzung.aus });
      return { ...basis, modus: "ki", ergebnis: { text: r.text.trim() }, hinweis: "" };
    } catch (e) {
      if (!(e instanceof KiFehler)) throw e;
      return regelAntwort(HINWEIS_AUSFALL, `ki-${e.art}`);
    }
  }

  // Streaming: Verbindung (inkl. Wiederholungen) VOR dem Antworten aufbauen – scheitert sie, Regelmodus als JSON
  let strom;
  try {
    strom = await streamen(anfrage);
  } catch (e) {
    if (!(e instanceof KiFehler)) throw e;
    return regelAntwort(HINWEIS_AUSFALL, `ki-${e.art}`);
  }

  const encoder = new TextEncoder();
  const lesbar = new ReadableStream({
    async start(controller) {
      const senden = (o) => controller.enqueue(encoder.encode(zeile(o)));
      let nutzung = { ein: 0, aus: 0 };
      let ergebnis = "ok";
      senden({ t: "start", ...basis, modus: "ki", hinweis: "" });
      try {
        for await (const e of strom.ereignisse()) {
          if (e.typ === "text") senden({ t: "text", text: e.text });
          else if (e.typ === "abgelehnt") {
            ergebnis = "ki-abgelehnt";
            senden({ t: "ersetzen", modus: "regel", ergebnis: def.regel(k, eingaben), hinweis: "Der KI-Dienst hat diese Anfrage nicht bearbeitet – hier ein regelbasierter Vorschlag." });
          } else if (e.typ === "ende") {
            nutzung = e.nutzung;
            if (e.stopReason === "max_tokens") senden({ t: "hinweis", hinweis: "Die Antwort wurde gekürzt." });
          }
        }
        senden({ t: "ende" });
      } catch (err) {
        ergebnis = "ki-abbruch";
        console.error("[plattform-ki] Stream abgebrochen:", err?.message);
        senden({ t: "ersetzen", modus: "regel", ergebnis: def.regel(k, eingaben), hinweis: HINWEIS_AUSFALL });
        senden({ t: "ende" });
      } finally {
        await protokollieren(n, { ...prot, modus: "ki", ergebnis, tokensEin: nutzung.ein, tokensAus: nutzung.aus });
        controller.close();
      }
    },
  });
  return new Response(lesbar, {
    status: 200,
    headers: { "Content-Type": "application/x-ndjson; charset=utf-8", "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" },
  });
}

/** Status für die Oberfläche */
export async function status(n) {
  const k = await kontingent(n);
  return { ok: true, aktiv: kiAktiv(), faelle: erlaubteFaelle(n), kontingent: { limit: k.limit, rest: k.rest } };
}
// src/lib/plattform/ki/konfig.js
//
// Konfiguration des KI-Assistenten (nur serverseitig). Der Assistent ist OPTIONAL:
// Ohne ANTHROPIC_API_KEY arbeitet jeder Anwendungsfall mit regelbasierten Vorschlägen
// (siehe regeln.js) – nie mit einem Fehler. Der Schlüssel verlässt nie den Server.
//
// Umgebungsvariablen (docs/PLATTFORM.md, Abschnitt „KI-Assistent“):
//   ANTHROPIC_API_KEY          Schlüssel der Claude API – ohne: regelbasierter Modus
//   KI_MODELL                  Modell-ID, Standard claude-opus-5-5
//   KI_TAGESKONTINGENT         Aufrufe je Konto und Tag (Standard 30), Backoffice: KI_TAGESKONTINGENT_ADMIN (Standard 150)
//   KI_AUS                     „1“ schaltet den KI-Modus ab (z. B. bei Störungen), Regeln bleiben aktiv
//   KI_FALLBACK                „aus“ deaktiviert den serverseitigen Ausweich-Modell-Mechanismus (fallbacks)

export const STANDARD_MODELL = "claude-opus-5-5";

/** Modelle, für die der serverseitige Ausweichmechanismus (`fallbacks: "default"`) gesetzt wird */
const MIT_FALLBACK = new Set(["claude-opus-5-5", "claude-opus-5", "claude-fable-5-1", "claude-sonnet-5-5"]);

export const ANWENDUNGSFAELLE = {
  expose: { label: "Exposé-Assistent", rollen: ["anbieter"] },
  triage: { label: "Anfrage-Zusammenfassung & Triage", admin: true },
  frage: { label: "Frag das Projekt", rollen: ["investor", "anbieter"] },
  flaeche: { label: "Flächen-Assistent", rollen: ["flaeche", "landwirt"] },
  nachricht: { label: "Nachrichten-Entwurf" },
};

export const FALL_IDS = Object.keys(ANWENDUNGSFAELLE);

export function kiAktiv() {
  return !!String(process.env.ANTHROPIC_API_KEY || "").trim() && process.env.KI_AUS !== "1";
}

export function kiModell() {
  return String(process.env.KI_MODELL || "").trim() || STANDARD_MODELL;
}

export function mitFallback(modell = kiModell()) {
  return process.env.KI_FALLBACK !== "aus" && MIT_FALLBACK.has(modell);
}

function zahl(wert, standard) {
  const n = Number(wert);
  return Number.isFinite(n) && n > 0 ? Math.floor(n) : standard;
}

/** Tages-Kontingent je Konto (Aufrufe des Assistenten, KI- und Regelmodus) */
export function tagesKontingent(nutzer) {
  const admin = !!nutzer?.rollen?.includes("admin");
  return admin ? zahl(process.env.KI_TAGESKONTINGENT_ADMIN, 150) : zahl(process.env.KI_TAGESKONTINGENT, 30);
}

/** Rate-Limit je Konto: [max, Fenster in ms] – kurzfristiger Schutz zusätzlich zum Tages-Kontingent */
export const RATE_KONTO = [8, 60e3];
/** Rate-Limit je IP (mehrere Konten hinter einer Adresse) */
export const RATE_IP = [30, 60e3];

/** Dev-Lockerung wie server/rateLimit.js (Standard Faktor 10 außerhalb Produktion) */
export function rateFaktor() {
  return process.env.NODE_ENV !== "production" ? Number(process.env.PLATTFORM_RATE_FAKTOR) || 10 : 1;
}
// src/lib/plattform/ki/client.js
//
// Schlanker Client für die Claude Messages API (POST /v1/messages) per fetch – ohne SDK-Paket
// (Projektregel: keine neuen npm-Pakete). Nur serverseitig verwenden.
//
//  - Zeitlimit je Versuch, Wiederholung mit exponentiellem Backoff bei 408/409/429/5xx/529 und
//    Netzwerkfehlern (Retry-After wird beachtet, gedeckelt)
//  - Prompt-Caching: stabile System-Blöcke tragen cache_control (Präfix bleibt byte-identisch)
//  - Serverseitiger Ausweichmechanismus bei Ablehnung durch Sicherheitsklassifikatoren
//    (`fallbacks: "default"`, Beta-Header server-side-fallback-2026-07-01)
//  - stop_reason wird immer geprüft („refusal“, „max_tokens“), bevor Inhalte verwendet werden
//  - Fehlertexte enthalten nie den Schlüssel oder Antwortinhalte

import { kiModell, mitFallback } from "./konfig";

const API_URL = "https://api.anthropic.com/v1/messages";
const API_VERSION = "2023-06-01";
const FALLBACK_BETA = "server-side-fallback-2026-07-01";
const WIEDERHOLBAR = new Set([408, 409, 429, 500, 502, 503, 504, 529]);

export class KiFehler extends Error {
  constructor(message, { status = 0, art = "fehler", wiederholbar = false } = {}) {
    super(message);
    this.name = "KiFehler";
    this.status = status;
    this.art = art; // fehler | abgelehnt | zeit | netz | konfig | abgeschnitten
    this.wiederholbar = wiederholbar;
  }
}

const warte = (ms) => new Promise((r) => setTimeout(r, ms));

function kopfzeilen() {
  const schluessel = String(process.env.ANTHROPIC_API_KEY || "").trim();
  if (!schluessel) throw new KiFehler("KI nicht konfiguriert.", { art: "konfig" });
  const h = { "content-type": "application/json", "x-api-key": schluessel, "anthropic-version": API_VERSION };
  if (mitFallback()) h["anthropic-beta"] = FALLBACK_BETA;
  return h;
}

/**
 * Anfragekörper. `system` = Liste stabiler Textblöcke (werden gecacht), `kontext` + `aufgabe`
 * landen in der Nutzer-Nachricht (wechselnder Teil NACH dem Cache-Präfix).
 */
export function koerper({ system = [], nachricht, maxTokens = 4000, effort = "low", schema = null, stream = false }) {
  const modell = kiModell();
  const bloecke = system.filter(Boolean).map((text, i, alle) => ({
    type: "text",
    text,
    ...(i === alle.length - 1 ? { cache_control: { type: "ephemeral" } } : {}),
  }));
  const k = {
    model: modell,
    max_tokens: maxTokens,
    system: bloecke,
    messages: [{ role: "user", content: nachricht }],
    output_config: { effort, ...(schema ? { format: { type: "json_schema", schema } } : {}) },
  };
  if (mitFallback(modell)) k.fallbacks = "default";
  if (stream) k.stream = true;
  return k;
}

function wartezeit(res, versuch) {
  const ra = Number(res?.headers?.get?.("retry-after"));
  if (Number.isFinite(ra) && ra > 0) return Math.min(ra * 1000, 8000);
  return Math.min(700 * 2 ** versuch + Math.random() * 300, 6000);
}

/** fetch mit Zeitlimit und Wiederholung; liefert eine erfolgreiche Response (Body ungelesen) */
async function senden(body, { versuche = 3, zeitlimitMs = 45000, signal } = {}) {
  let letzter;
  for (let versuch = 0; versuch < versuche; versuch++) {
    let res;
    try {
      const zeit = AbortSignal.timeout(zeitlimitMs);
      res = await fetch(API_URL, {
        method: "POST",
        headers: kopfzeilen(),
        body: JSON.stringify(body),
        cache: "no-store",
        signal: signal ? AbortSignal.any([signal, zeit]) : zeit,
      });
    } catch (e) {
      if (e instanceof KiFehler) throw e;
      if (signal?.aborted) throw new KiFehler("Abgebrochen.", { art: "abbruch" });
      const zeitueberschreitung = e?.name === "TimeoutError" || e?.name === "AbortError";
      letzter = new KiFehler(zeitueberschreitung ? "Zeitüberschreitung beim KI-Dienst." : "KI-Dienst nicht erreichbar.", { art: zeitueberschreitung ? "zeit" : "netz", wiederholbar: true });
      if (versuch < versuche - 1) await warte(wartezeit(null, versuch));
      continue;
    }
    if (res.ok) return res;
    // Fehlertyp nur für das Server-Log – Inhalte der Antwort nie weitergeben
    let typ = "";
    try {
      typ = (await res.json())?.error?.type || "";
    } catch {
      /* kein JSON */
    }
    console.error(`[plattform-ki] Claude API HTTP ${res.status} ${typ}`);
    letzter = new KiFehler("KI-Dienst hat die Anfrage nicht verarbeitet.", { status: res.status, wiederholbar: WIEDERHOLBAR.has(res.status) });
    if (!letzter.wiederholbar) throw letzter;
    if (versuch < versuche - 1) await warte(wartezeit(res, versuch));
  }
  throw letzter || new KiFehler("KI-Dienst nicht erreichbar.");
}

function nutzungAus(u = {}) {
  return {
    ein: (u.input_tokens || 0) + (u.cache_read_input_tokens || 0) + (u.cache_creation_input_tokens || 0),
    aus: u.output_tokens || 0,
    cache: u.cache_read_input_tokens || 0,
  };
}

function stopPruefen(stopReason) {
  if (stopReason === "refusal") throw new KiFehler("Der KI-Dienst hat die Anfrage abgelehnt.", { art: "abgelehnt" });
}

/** Nicht-streamende Anfrage. Liefert { text, json?, stopReason, nutzung, modell } */
export async function erstellen(optionen) {
  const body = koerper({ ...optionen, stream: false });
  const res = await senden(body, { zeitlimitMs: optionen.zeitlimitMs || 60000, signal: optionen.signal });
  const m = await res.json();
  stopPruefen(m.stop_reason);
  const text = (m.content || []).filter((b) => b.type === "text").map((b) => b.text).join("");
  const out = { text, stopReason: m.stop_reason, nutzung: nutzungAus(m.usage), modell: m.model };
  if (optionen.schema) {
    if (m.stop_reason === "max_tokens") throw new KiFehler("Antwort unvollständig.", { art: "abgeschnitten" });
    try {
      out.json = JSON.parse(text);
    } catch {
      throw new KiFehler("Antwort nicht lesbar.", { art: "fehler" });
    }
  }
  return out;
}

/**
 * Streamende Anfrage. Wartet auf die Kopfzeilen (Fehler/Wiederholungen VOR dem ersten Token),
 * danach liefert `ereignisse()` Textstücke: { typ: "text", text } … { typ: "ende", stopReason, nutzung, modell }.
 * Eine Ablehnung mitten im Stream kommt als { typ: "abgelehnt" } (Teilausgabe verwerfen).
 */
export async function streamen(optionen) {
  const body = koerper({ ...optionen, stream: true });
  const res = await senden(body, { zeitlimitMs: optionen.zeitlimitMs || 120000, signal: optionen.signal });
  async function* ereignisse() {
    const reader = res.body.getReader();
    const decoder = new TextDecoder();
    let puffer = "";
    let nutzung = { ein: 0, aus: 0, cache: 0 };
    let stopReason = null;
    let modell = "";
    let textBloecke = new Set();
    try {
      for (;;) {
        const { value, done } = await reader.read();
        if (done) break;
        puffer += decoder.decode(value, { stream: true });
        let grenze;
        while ((grenze = puffer.indexOf("\n\n")) >= 0) {
          const roh = puffer.slice(0, grenze);
          puffer = puffer.slice(grenze + 2);
          const zeile = roh.split("\n").find((z) => z.startsWith("data:"));
          if (!zeile) continue;
          let e;
          try {
            e = JSON.parse(zeile.slice(5).trim());
          } catch {
            continue;
          }
          if (e.type === "message_start") {
            modell = e.message?.model || modell;
            const u = nutzungAus(e.message?.usage);
            nutzung = { ...u, aus: nutzung.aus };
          } else if (e.type === "content_block_start" && e.content_block?.type === "text") {
            textBloecke.add(e.index);
          } else if (e.type === "content_block_delta" && e.delta?.type === "text_delta" && textBloecke.has(e.index)) {
            yield { typ: "text", text: e.delta.text };
          } else if (e.type === "message_delta") {
            stopReason = e.delta?.stop_reason || stopReason;
            if (e.usage?.output_tokens) nutzung.aus = e.usage.output_tokens;
          } else if (e.type === "error") {
            console.error(`[plattform-ki] Stream-Fehler ${e.error?.type || ""}`);
            throw new KiFehler("KI-Dienst hat den Vorgang abgebrochen.", { art: "fehler" });
          }
        }
      }
    } finally {
      reader.releaseLock?.();
    }
    if (stopReason === "refusal") {
      yield { typ: "abgelehnt" };
      return;
    }
    yield { typ: "ende", stopReason, nutzung, modell };
  }
  return { ereignisse };
}

// src/lib/plattform/ki/prompts.js
//
// Prompt-Bausteine je Anwendungsfall. Aufbau für Prompt-Caching:
//   system  = [BASIS, FALL_TEXT (, WISSEN)]  – feste Texte, byte-identisch zwischen Anfragen
